using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace PriceCalculator.Tests;

/// <summary>
/// Example PriceCalculator under test.
/// </summary>
public class PriceCalculator
{
    public decimal CalculateTotal(decimal unitPrice, int quantity) =>
        unitPrice * quantity;

    public decimal ApplyDiscount(decimal total, decimal discountPercent)
    {
        if (discountPercent < 0 || discountPercent > 100)
            throw new ArgumentOutOfRangeException(nameof(discountPercent));

        return total - (total * discountPercent / 100m);
    }
}

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ─── DataRow: inline constant data ───────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(10.00, 5, 50.00, DisplayName = "Multiple items")]
    [DataRow(0.00, 10, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.00, DisplayName = "Zero quantity")]
    [DataRow(0.01, 100, 1.00, DisplayName = "Small unit price")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "No discount")]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off")]
    [DataRow(100.00, 50.0, 50.00, DisplayName = "50% off")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% off")]
    [DataRow(49.99, 25.0, 37.4925, DisplayName = "Fractional result")]
    public void ApplyDiscount_ReturnsExpected(
        double total, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Negative discount throws")]
    [DataRow(101.0, DisplayName = "Over 100% throws")]
    public void ApplyDiscount_InvalidPercent_Throws(double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }

    // ─── DynamicData: complex/decimal-precise test cases ─────────────────

    [TestMethod]
    [DynamicData(nameof(CalculateTotalCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_DynamicCases(
        decimal unitPrice, int quantity, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity);

        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> CalculateTotalCases()
    {
        yield return new object[] { 19.99m, 3, 59.97m };
        yield return new object[] { 1000.00m, 100, 100_000.00m };
        yield return new object[] { 0.001m, 1000, 1.000m };
    }

    [TestMethod]
    [DynamicData(nameof(DiscountCases), DynamicDataSourceType.Property)]
    public void ApplyDiscount_DynamicCases(
        decimal total, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> DiscountCases =>
        new List<object[]>
        {
            new object[] { 200.00m, 15.0m, 170.00m },
            new object[] { 59.97m, 20.0m, 47.976m },
            new object[] { 0.00m, 50.0m, 0.00m },
        };
}

